	interface Props {
		provider?: string | null;
		size?: number | string;
		class?: string;
		style?: string;
		title?: string;
		ariaHidden?: boolean;
	}

	let {
		provider = '',
		size,
		class: className = '',
		style = '',
		title = '',
		ariaHidden = true
	}: Props = $props();

	const resolvedId = $derived<ResolvedProviderId>(normalizeProviderId(provider));
	const localLogo = $derived(localLogos[resolvedId]);
	const sizeStyle = $derived(
		size !== undefined
			? `--icon-size: ${typeof size === 'number' ? `${size}px` : size};`
			: ''
	);
	// ID univoco per istanza montata, per isolare gradienti, maschere e filtri SVG
	const uid = $props.id();
</script>

